def _imagen_logo_sns():
    datos = base64.b64decode(_LOGO_SNS_B64)
    img = XLImage(io.BytesIO(datos))
    img.width = 90
    img.height = 30
    return img

def _pascua_gregoriana(anio):
    """Domingo de Pascua (algoritmo de Meeus/Jones/Butcher)."""
    a = anio % 19
    b = anio // 100
    c = anio % 100
    d = b // 4
    e = b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i = c // 4
    k = c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    mes = (h + l - 7 * m + 114) // 31
    dia = ((h + l - 7 * m + 114) % 31) + 1
    return datetime.date(anio, mes, dia)

def _mover_a_lunes(fecha):
    """Ley 139-97: si el feriado no cae lunes, se traslada al lunes siguiente."""
    if fecha.weekday() == 0:
        return fecha
    dias_hasta_lunes = (7 - fecha.weekday()) % 7
    return fecha + datetime.timedelta(days=dias_hasta_lunes)

def obtener_feriados_dominicanos(anio):
    """Feriados oficiales de República Dominicana para el año dado."""
    pascua = _pascua_gregoriana(anio)
    viernes_santo = pascua - datetime.timedelta(days=2)
    corpus_christi = pascua + datetime.timedelta(days=60)
    return {
        datetime.date(anio, 1, 1): "Año Nuevo",
        _mover_a_lunes(datetime.date(anio, 1, 6)): "Día de Reyes",
        datetime.date(anio, 1, 21): "Día de la Altagracia",
        _mover_a_lunes(datetime.date(anio, 1, 26)): "Día de Duarte",
        datetime.date(anio, 2, 27): "Independencia Nacional",
        viernes_santo: "Viernes Santo",
        _mover_a_lunes(datetime.date(anio, 5, 1)): "Día del Trabajo",
        corpus_christi: "Corpus Christi",
        _mover_a_lunes(datetime.date(anio, 8, 16)): "Restauración",
        datetime.date(anio, 9, 24): "Ntra. Sra. de las Mercedes",
        _mover_a_lunes(datetime.date(anio, 11, 6)): "Día de la Constitución",
        datetime.date(anio, 12, 25): "Navidad",
    }

def obtener_dias_no_laborables(anio, mes_num):
    """Devuelve {dia: motivo} para sábados, domingos y feriados del mes."""
    feriados_anio = obtener_feriados_dominicanos(anio)
    resultado = {}
    _, dias_en_mes = calendar.monthrange(anio, mes_num)
    for dia in range(1, dias_en_mes + 1):
        fecha = datetime.date(anio, mes_num, dia)
        if fecha.weekday() == 5:
            resultado[dia] = "Sábado"
        elif fecha.weekday() == 6:
            resultado[dia] = "Domingo"
        elif fecha in feriados_anio:
            resultado[dia] = feriados_anio[fecha]
    return resultado

def _sin_acentos(texto):
    nfkd = unicodedata.normalize('NFKD', texto or "")
    return ''.join(c for c in nfkd if not unicodedata.combining(c))

def clave_orden_persona(persona):
    """Clave alfabética estable por nombre y luego apellidos."""
    nombre = _sin_acentos(str(persona.get("nombre") or "")).casefold().strip()
    apellidos = _sin_acentos(str(persona.get("apellidos") or "")).casefold().strip()
    return nombre, apellidos

# ==================================================================
# CATEGORÍA ÚNICA DE CARGO — fuente de verdad para tarifa, sueldo Y
# para decidir si alguien es "Promotor" o no. Todo se deriva del texto
# de "cargo" que está en Personal Registrado, nunca de un campo aparte.
# El ORDEN importa: "SUPERVISOR (A) DE PROMOTORES" contiene la palabra
# "PROMOTORES", así que SUPERVISOR debe revisarse antes que PROMOTOR
# para no clasificar mal a los supervisores.
# ==================================================================
CATEGORIAS_CARGO = [
    ("PSICOLOG", "PSICOLOGO", 700, 50242.50),      # cubre psicólogo/a, con o sin acento
    ("SUPERVISOR", "SUPERVISOR", 400, 25000.00),
    ("PROMOTOR", "PROMOTOR", 300, 15000.00),
]
CATEGORIA_DEFECTO = ("OTRO", 500, 0.00)  # enfermeras, analistas y demás cargos no listados

def categorizar_cargo(cargo):
    """Devuelve (categoria, tarifa_diaria, sueldo_sugerido) según el texto del cargo."""
    cargo_norm = _sin_acentos(cargo).upper()
    for clave, categoria, tarifa, sueldo in CATEGORIAS_CARGO:
        if clave in cargo_norm:
            return categoria, tarifa, sueldo
    return CATEGORIA_DEFECTO

def tarifa_estandar(cargo):
    _, tarifa, _ = categorizar_cargo(cargo)
    return tarifa

def asignacion_diaria_persona(cargo, asignacion_guardada=None):
    """Devuelve la asignación guardada o la tarifa estándar del cargo.

    Los valores cero, vacíos o inválidos se consideran sin asignación
    personalizada y usan la tarifa estándar vigente.
    """
    try:
        valor_guardado = float(asignacion_guardada)
        if valor_guardado > 0:
            return valor_guardado
    except (TypeError, ValueError):
        pass
    return tarifa_estandar(cargo)

def sueldo_estandar(cargo):
    _, _, sueldo = categorizar_cargo(cargo)
    return sueldo

def es_cargo_promotor(cargo):
    """Único criterio para saber si alguien es Promotor: su CARGO real
    registrado en Personal Registrado — nunca un campo 'tipo' aparte."""
    categoria, _, _ = categorizar_cargo(cargo)
    return categoria == "PROMOTOR"

