def migrar_columnas():
    with sqlite3.connect(DB_NAME, timeout=60.0) as conn:
        cursor = conn.cursor()
        cursor.execute("PRAGMA table_info(promotores)")
        columnas_existentes = [c[1] for c in cursor.fetchall()]
        if "tipo" not in columnas_existentes:
            cursor.execute("ALTER TABLE promotores ADD COLUMN tipo TEXT DEFAULT 'PROMOTOR'")
        if "asignacion_diaria" not in columnas_existentes:
            cursor.execute("ALTER TABLE promotores ADD COLUMN asignacion_diaria REAL DEFAULT 0")
        if "sueldo" not in columnas_existentes:
            cursor.execute("ALTER TABLE promotores ADD COLUMN sueldo REAL DEFAULT 0")
        cursor.execute("""CREATE TABLE IF NOT EXISTS notas_cronograma (
            promotor_id INTEGER, periodo TEXT, dia INTEGER, nota TEXT, region TEXT,
            PRIMARY KEY (promotor_id, periodo, dia, region)
        )""")
        conn.commit()

def reparar_asignaciones_diarias():
    """Completa la asignación estándar para registros antiguos sin monto.

    Un valor positivo siempre se respeta porque representa una tarifa
    personalizada elegida por el usuario.
    """
    with sqlite3.connect(DB_NAME, timeout=60.0) as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT id, cargo, asignacion_diaria FROM promotores")
        for pid, cargo, asignacion_guardada in cursor.fetchall():
            try:
                tiene_asignacion = float(asignacion_guardada or 0) > 0
            except (TypeError, ValueError):
                tiene_asignacion = False
            if not tiene_asignacion:
                cursor.execute(
                    "UPDATE promotores SET asignacion_diaria=? WHERE id=?",
                    (tarifa_estandar(cargo), pid),
                )
        conn.commit()
