inicializar_tablas_tb(DB_NAME)

def reparar_tipos_por_cargo():
    """Corrige 'tipo' para TODO el personal ya existente, recalculándolo a
    partir de su cargo real (columna 'cargo' en Personal Registrado). Esto
    arregla los registros que quedaron mal por defecto (todos 'PROMOTOR')
    al agregar la columna 'tipo' en una versión anterior del sistema."""
    with sqlite3.connect(DB_NAME, timeout=60.0) as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT id, cargo, tipo FROM promotores")
        filas = cursor.fetchall()
        for pid, cargo, tipo_actual in filas:
            tipo_correcto = "PROMOTOR" if es_cargo_promotor(cargo) else "SUPERVISOR"
            if tipo_correcto != tipo_actual:
                cursor.execute("UPDATE promotores SET tipo=? WHERE id=?", (tipo_correcto, pid))
        conn.commit()

