def verificar_login(usuario, password):
    pass_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()
    with sqlite3.connect(DB_NAME) as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT region, rol FROM usuarios WHERE usuario=? AND password=?", (usuario.strip().upper(), pass_hash))
        return cursor.fetchone()

def obtener_periodo_activo(region):
    with sqlite3.connect(DB_NAME) as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT valor FROM parametros WHERE clave='MES_ACTUAL' AND region=?", (region,))
        mes = cursor.fetchone()
        cursor.execute("SELECT valor FROM parametros WHERE clave='ANIO_ACTUAL' AND region=?", (region,))
        anio = cursor.fetchone()
    if not mes or not anio:
        with sqlite3.connect(DB_NAME) as conn:
            cursor = conn.cursor()
            cursor.execute("INSERT OR IGNORE INTO parametros VALUES ('MES_ACTUAL', ?, 'AGOSTO')", (region,))
            cursor.execute("INSERT OR IGNORE INTO parametros VALUES ('ANIO_ACTUAL', ?, '2026')", (region,))
            conn.commit()
        return "AGOSTO", "2026"
    return mes[0], anio[0]

def cambiar_periodo(mes, anio, region):
    with sqlite3.connect(DB_NAME) as conn:
        cursor = conn.cursor()
        cursor.execute("INSERT OR REPLACE INTO parametros VALUES ('MES_ACTUAL', ?, ?)", (region, str(mes).strip().upper()))
        cursor.execute("INSERT OR REPLACE INTO parametros VALUES ('ANIO_ACTUAL', ?, ?)", (region, str(anio).strip()))
        conn.commit()

# ==================================================================
# GENERACIÓN DE EXPEDIENTES — clonando la plantilla maestra oficial
# ==================================================================

def _clonar_imagenes(ws_origen, ws_destino):
    for img in ws_origen._images:
        datos = img.ref.getvalue() if hasattr(img.ref, "getvalue") else img._data()
        nueva = XLImage(io.BytesIO(datos))
        nueva.anchor = copy.deepcopy(img.anchor)
        ws_destino.add_image(nueva)

def _titulo_unico(base, usados):
    base = (base or "SIN NOMBRE").strip()
    for ch in '/\\*?[]:':
        base = base.replace(ch, "")
    base = base[:31] or "SIN NOMBRE"
    if base in usados:
        usados[base] += 1
        sufijo = f" ({usados[base]})"
        base = base[: 31 - len(sufijo)] + sufijo
    else:
        usados[base] = 0
    return base

def _calcular_posicion_calendario(anio, mes_num, dia):
    """Devuelve (fila_contenido, columna_indice) dentro de la grilla del Calendario
    para un día calendario dado, replicando la misma lógica de anclaje a lunes
    que usan las fórmulas originales del archivo (K13 = AC6-AD6)."""
    primer_dia = datetime.date(anio, mes_num, 1)
    lunes_ancla = primer_dia - datetime.timedelta(days=primer_dia.weekday())
    fecha_objetivo = datetime.date(anio, mes_num, dia)
    offset_dias = (fecha_objetivo - lunes_ancla).days
    bloque = offset_dias // 14
    col_en_bloque = offset_dias % 14
    fila_contenido = 14 + bloque * 3
    col_idx = 11 + col_en_bloque  # K = columna 11
    return fila_contenido, col_idx

def _etiqueta_rol_persona(persona):
    """Rótulo para la celda B7: 'Promotor' para promotores (según su
    cargo real), o el cargo real (Supervisor(a) de Promotores, Psicólogo,
    Enfermera, etc.) para el resto del personal."""
    if es_cargo_promotor(persona.get("cargo")):
        return "Promotor"
    return (persona.get("cargo") or "Personal").strip().title()

def _sueldo_persona(persona):
    """Sueldo guardado para la persona; si no tiene uno guardado (0, None
    o vacío) usa el sueldo estándar sugerido según su cargo."""
    sueldo_guardado = persona.get("sueldo")
    try:
        sueldo_guardado = float(sueldo_guardado) if sueldo_guardado not in (None, "") else 0.0
    except (TypeError, ValueError):
        sueldo_guardado = 0.0
    if sueldo_guardado > 0:
        return sueldo_guardado
    return sueldo_estandar(persona.get("cargo"))

def _texto_identificador_excel(valor, es_cedula=False):
    """Convierte cédulas y cuentas en texto para conservar ceros iniciales."""
    if valor is None:
        return ""
    if isinstance(valor, float) and valor.is_integer():
        texto = str(int(valor))
    else:
        texto = str(valor).strip()
        if texto.endswith(".0") and texto[:-2].isdigit():
            texto = texto[:-2]
    if es_cedula and texto.isdigit():
        # La cédula dominicana tiene 11 dígitos; esto recupera el cero
        # inicial cuando un archivo externo la entregó como número.
        texto = texto.zfill(11)
    return texto

def _escribir_identificador_excel(celda, valor, es_cedula=False):
    celda.value = _texto_identificador_excel(valor, es_cedula=es_cedula)
    celda.number_format = "@"
    celda.data_type = "s"

def _limpiar_firma_final(ws, persona=None):
    """Deja dos espacios de firma alineados horizontalmente."""
    for rango in ("B58:C58", "B59:C59", "J58:K58", "J59:K59"):
        try:
            ws.unmerge_cells(rango)
        except Exception:
            pass
    for coord in (
        "B58", "C58", "D58", "E58", "F58", "G58", "H58", "I58", "J58", "K58",
        "B59", "C59", "D59", "E59", "F59", "G59", "H59", "I59", "J59", "K59",
    ):
        ws[coord] = None

    nombre_colaborador = f"{persona.get('nombre', '')} {persona.get('apellidos', '')}".strip() if persona else ""
    nombre_colaborador = nombre_colaborador or "Colaborador"

    # Firma de la Dra. Yaneiris Cuevas a la izquierda.
    ws.merge_cells("B58:E58")
    ws["B58"] = "_____________________________"
    ws["B58"].alignment = Alignment(horizontal="center")
    ws.merge_cells("B59:E59")
    ws["B59"] = "Dra. Yaneiris Cuevas"
    ws["B59"].alignment = Alignment(horizontal="center")
    ws["B59"].font = Font(bold=True, size=10)

    # Firma del colaborador a la derecha, sin anteponer "Colaborador:".
    ws.merge_cells("G58:K58")
    ws["G58"] = "_____________________________"
    ws["G58"].alignment = Alignment(horizontal="center")
    ws.merge_cells("G59:K59")
    ws["G59"] = nombre_colaborador
    ws["G59"].alignment = Alignment(horizontal="center", wrap_text=True)
    ws["G59"].font = Font(bold=True, size=10)

def _generar_hoja_promotor(wb, plant_pristina, persona, dias_info, mes_nombre_excel, anio, usados):
    ws = wb.copy_worksheet(plant_pristina)
    _clonar_imagenes(plant_pristina, ws)
    nombre_completo = f"{persona['nombre']} {persona['apellidos']}".strip()
    ws.title = _titulo_unico(nombre_completo, usados)

    tarifa = asignacion_diaria_persona(
        persona.get("cargo"),
        persona.get("asignacion_diaria"),
    )
    sueldo = _sueldo_persona(persona)

    ws["A4"] = "DIRECCIÓN DE ASISTENCIA A LA RED"
    ws["B7"] = "Promotor"
    ws["E7"] = nombre_completo
    ws["E8"] = persona.get("cargo") or ""
    ws["J7"] = mes_nombre_excel
    ws["J49"] = anio
    ws["D10"] = tarifa
    ws[CELDA_SUELDO_PLANTILLA] = sueldo
    ws["A15"] = 1  # rompe el enlace DAY(Calendario!AC6); la cadena A16=A15+1... sigue funcionando

    for dia in range(1, 32):
        info = dias_info.get(dia)
        valor = ""
        if info and info.get("visito"):
            valor = info.get("centro") or "VISITA REALIZADA"
        ws.cell(row=14 + dia, column=4, value=valor)  # columna D

    _limpiar_firma_final(ws, persona)
    return ws, tarifa

def _generar_par_supervisor(wb, plant_pristina, cal_pristina, persona, dias_info, mes_nombre_excel, anio, mes_num, usados):
    nombre_completo = f"{persona['nombre']} {persona['apellidos']}".strip()

    ws_cal = wb.copy_worksheet(cal_pristina)
    _clonar_imagenes(cal_pristina, ws_cal)
    ws_cal.title = _titulo_unico(f"Calendario {nombre_completo}", usados)

    ws_plant = wb.copy_worksheet(plant_pristina)
    _clonar_imagenes(plant_pristina, ws_plant)
    ws_plant.title = _titulo_unico(f"Plantilla {nombre_completo}", usados)

    for row in ws_plant.iter_rows():
        for cell in row:
            if isinstance(cell.value, str) and "'Plantilla Calendario'!" in cell.value:
                cell.value = cell.value.replace("'Plantilla Calendario'!", f"'{ws_cal.title}'!")

    ws_cal["B9"] = anio
    ws_cal["C9"] = mes_nombre_excel
    ws_cal["C14"] = nombre_completo

    tarifa = asignacion_diaria_persona(
        persona.get("cargo"),
        persona.get("asignacion_diaria"),
    )
    sueldo = _sueldo_persona(persona)
    etiqueta_rol = _etiqueta_rol_persona(persona)

    ws_plant["A4"] = "DIRECCIÓN DE ASISTENCIA A LA RED"
    ws_plant["B7"] = etiqueta_rol
    ws_plant["E8"] = persona.get("cargo") or ""
    ws_plant["D10"] = tarifa
    ws_plant[CELDA_SUELDO_PLANTILLA] = sueldo

    for dia, info in dias_info.items():
        if info.get("visito"):
            fila, col = _calcular_posicion_calendario(anio, mes_num, dia)
            texto = info.get("nota") or info.get("centro") or "VISITA REALIZADA"
            ws_cal.cell(row=fila, column=col, value=texto)

    _limpiar_firma_final(ws_plant, persona)
    return ws_plant, ws_cal, tarifa

def _construir_hoja_consolidado(wb, region_actual, periodo_act, filas_personas):
    """Replica EXACTAMENTE el formato del Consolidado oficial (letra, colores,
    anchos de columna, formatos de fecha/moneda) tal como viene en el archivo
    CONSOLIDADO_OZAMA_AGOSTO_2026_TRANSPORTE.xlsx enviado como modelo."""
    ws = wb.create_sheet(title="Consolidado", index=0)
    thin = Side(style="thin")
    medium = Side(style="medium")
    borde_dato = Border(left=thin, right=thin, top=thin, bottom=thin)
    borde_header = Border(top=medium, bottom=thin)

    fuente_titulo = Font(name="Times New Roman", size=11, bold=True)
    fuente_header = Font(name="Calibri", size=11, bold=False, color="FFFFFFFF")
    fill_header = PatternFill(fill_type="solid", fgColor="FF002060")
    formato_fecha = "dd/mm/yyyy;@"
    # Formato contable: símbolo RD$ alineado a la izquierda de la celda y el
    # número alineado a la derecha, como en un estado de cuenta.
    formato_moneda = '_-"RD$"* #,##0.00_-;-"RD$"* #,##0.00_-;_-"RD$"* "-"??_-;_-@_-'

    logo = _imagen_logo_sns()
    ws.add_image(logo, "A1")

    ws.merge_cells("A6:E6"); ws["A6"] = "SERVICIO NACIONAL DE SALUD"
    ws.merge_cells("A7:E7"); ws["A7"] = f"DIRECCIÓN DE GESTIÓN CLÍNICA — {region_actual}"
    ws.merge_cells("A8:E8"); ws["A8"] = f"TRANSPORTE — MES DE {periodo_act}"
    for fila in (6, 7, 8):
        ws.cell(row=fila, column=1).font = fuente_titulo
        ws.row_dimensions[fila].height = 13.8

    encabezados = ["NO.", "NOMBRE", "APELLIDOS", "FECHA VISITA", "TRANSP.", "MONTO TOTAL", "CEDULA", "NO. DE CUENTA", "LUGAR VISITADO", "DEF_CARGO"]
    for idx, texto in enumerate(encabezados, start=1):
        c = ws.cell(row=9, column=idx, value=texto)
        c.font = fuente_header
        c.fill = fill_header
        c.border = borde_header
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    fila_actual = 10
    total_general = 0.0
    for no_persona, persona in enumerate(filas_personas, start=1):
        dias = persona["dias"]
        if not dias:
            continue
        fila_inicio = fila_actual
        for i, (fecha_valor, monto, lugar) in enumerate(dias):
            if i == 0:
                for col, valor in (
                    (1, no_persona),
                    (2, persona["nombre"]),
                    (3, persona["apellidos"]),
                    (10, persona["cargo"]),
                ):
                    ws.cell(row=fila_actual, column=col, value=valor).font = Font(bold=True)
                celda_cedula = ws.cell(row=fila_actual, column=7)
                _escribir_identificador_excel(
                    celda_cedula,
                    persona["cedula"],
                    es_cedula=True,
                )
                celda_cedula.font = Font(bold=True)
                celda_cuenta = ws.cell(row=fila_actual, column=8)
                _escribir_identificador_excel(celda_cuenta, persona["cuenta"])
                celda_cuenta.font = Font(bold=True)
            cd = ws.cell(row=fila_actual, column=4, value=fecha_valor)
            cd.number_format = formato_fecha
            ce = ws.cell(row=fila_actual, column=5, value=monto)
            ce.number_format = formato_moneda
            cf = ws.cell(row=fila_actual, column=6, value=monto)
            cf.number_format = formato_moneda
            ws.cell(row=fila_actual, column=9, value=lugar).font = Font(bold=True)
            fila_actual += 1
        subtotal = sum(m for _, m, _ in dias)
        ce_sub = ws.cell(row=fila_actual, column=5, value=subtotal)
        ce_sub.font = Font(bold=True); ce_sub.number_format = formato_moneda
        cf_sub = ws.cell(row=fila_actual, column=6, value=subtotal)
        cf_sub.font = Font(bold=True); cf_sub.number_format = formato_moneda
        total_general += subtotal
        fila_fin = fila_actual
        for col in (1, 2, 3, 7, 8, 10):
            if fila_fin > fila_inicio:
                ws.merge_cells(start_row=fila_inicio, start_column=col, end_row=fila_fin, end_column=col)
        for f in range(fila_inicio, fila_fin + 1):
            for c in range(1, 11):
                ws.cell(row=f, column=c).border = borde_dato
        fila_actual += 1

    ws.cell(row=fila_actual + 1, column=4, value="TOTAL TRANSP.:").font = Font(bold=True)
    te = ws.cell(row=fila_actual + 1, column=5, value=total_general)
    te.font = Font(bold=True); te.number_format = formato_moneda
    ws.cell(row=fila_actual + 1, column=5).alignment = Alignment(horizontal="right")

    ws.cell(row=fila_actual + 2, column=5, value="TOTAL GENERAL:").font = Font(bold=True)
    tg = ws.cell(row=fila_actual + 2, column=6, value=total_general)
    tg.font = Font(bold=True); tg.number_format = formato_moneda

    anchos = {
        "A": 5.21875, "B": 26, "C": 35.44140625, "D": 14.33203125, "E": 16.33203125,
        "F": 15.6640625, "G": 20.77734375, "H": 14.33203125, "I": 64.5546875, "J": 48.44140625,
    }
    for col, ancho in anchos.items():
        ws.column_dimensions[col].width = ancho
    return total_general

def _construir_hoja_sigef(wb, filas_personas):
    """Replica la hoja SIGEF del archivo modelo: listado plano (una fila por
    persona) con el monto TOTAL del mes, para importar al sistema SIGEF."""
    ws = wb.create_sheet(title="SIGEF")
    encabezados = ["CÉDULA", "NOMBRE", "APELLIDO", "CARGO", "CTA. BANCARIA", "LUGAR DESIGNADO NOMINA", "MONTO"]
    for idx, texto in enumerate(encabezados, start=1):
        ws.cell(row=1, column=idx, value=texto)

    fila = 2
    for persona in filas_personas:
        total_persona = sum(m for _, m, _ in persona["dias"])
        if total_persona <= 0:
            continue
        _escribir_identificador_excel(
            ws.cell(row=fila, column=1),
            persona["cedula"],
            es_cedula=True,
        )
        ws.cell(row=fila, column=2, value=persona["nombre"])
        ws.cell(row=fila, column=3, value=persona["apellidos"])
        ws.cell(row=fila, column=4, value=persona["cargo"])
        _escribir_identificador_excel(ws.cell(row=fila, column=5), persona["cuenta"])
        ws.cell(row=fila, column=6, value=persona.get("lugar_nomina") or "SECCION DE TB- SRS METROPOLITANO")
        ws.cell(row=fila, column=7, value=total_persona)
        fila += 1

    anchos = {"A": 15, "B": 22.88671875, "C": 30.6640625, "D": 37.88671875, "E": 17.6640625, "F": 64.33203125, "G": 11.88671875}
    for col, ancho in anchos.items():
        ws.column_dimensions[col].width = ancho
    return ws

def construir_libro_expedientes(personas_seleccionadas, personas_consolidado, region, periodo_str, mes_texto, anio_texto):
    """
    personas_seleccionadas: lista de dicts (id, nombre, apellidos, cedula, cargo, tipo, sueldo) —
        para estas se genera la Plantilla (y Calendario si no son promotor).
    personas_consolidado: lista de TODO el personal con actividad ese mes (para la hoja Consolidado),
        sin importar si se seleccionaron o no para imprimir su expediente individual.
    """
    # La plantilla, el consolidado y las hojas individuales deben salir
    # siempre en el mismo orden alfabético, independientemente del orden
    # en que SQLite o la interfaz entreguen los registros.
    personas_seleccionadas = sorted(
        personas_seleccionadas or [],
        key=clave_orden_persona,
    )
    personas_consolidado = sorted(
        personas_consolidado or [],
        key=clave_orden_persona,
    )

    mes_num = MESES_NUM.get(mes_texto.strip().upper(), 1)
    mes_nombre_excel = MESES_NOMBRE_EXCEL.get(mes_texto.strip().upper(), mes_texto.title())
    try:
        anio_num = int(anio_texto)
    except (TypeError, ValueError):
        anio_num = datetime.date.today().year

    wb_maestro = _cargar_maestro_viaticos()
    plant_pristina = wb_maestro["Plantilla Calculo Viaticos"]
    cal_pristina = wb_maestro["Plantilla Calendario"]
    usados = {}

    with sqlite3.connect(DB_NAME) as conn:
        cursor = conn.cursor()

        # ---- Hoja Consolidado (todo el personal con actividad este mes) ----
        filas_consolidado = []
        for persona in personas_consolidado:
            cursor.execute(
                "SELECT dia, monto, centro_visitado FROM visitas WHERE promotor_id=? AND periodo=? AND region=? AND visito=1 ORDER BY dia",
                (persona["id"], periodo_str, region)
            )
            dias_persona = []
            for dia, monto, centro in cursor.fetchall():
                try:
                    fecha_valor = datetime.date(anio_num, mes_num, dia)
                except ValueError:
                    fecha_valor = f"{mes_texto} {dia}"
                dias_persona.append((fecha_valor, monto or 0, centro or ""))
            if dias_persona:
                filas_consolidado.append({
                    "nombre": persona["nombre"], "apellidos": persona["apellidos"],
                    "cedula": persona["cedula"], "cuenta": persona.get("cuenta", ""),
                    "cargo": persona.get("cargo", ""), "lugar_nomina": persona.get("lugar_nomina", ""),
                    "dias": dias_persona,
                })
        _construir_hoja_consolidado(wb_maestro, region, periodo_str, filas_consolidado)
        _construir_hoja_sigef(wb_maestro, filas_consolidado)

        # ---- Hojas individuales (solo el personal seleccionado) ----
        for persona in personas_seleccionadas:
            cursor.execute(
                "SELECT dia, visito, monto, centro_visitado FROM visitas WHERE promotor_id=? AND periodo=? AND region=?",
                (persona["id"], periodo_str, region)
            )
            dias_info = {}
            for dia, visito, monto, centro in cursor.fetchall():
                dias_info[dia] = {"visito": bool(visito), "monto": monto or 0, "centro": centro or ""}

            if es_cargo_promotor(persona.get("cargo")):
                _generar_hoja_promotor(wb_maestro, plant_pristina, persona, dias_info, mes_nombre_excel, anio_num, usados)
            else:
                cursor.execute(
                    "SELECT dia, nota FROM notas_cronograma WHERE promotor_id=? AND periodo=? AND region=?",
                    (persona["id"], periodo_str, region)
                )
                for dia, nota in cursor.fetchall():
                    if dia in dias_info:
                        dias_info[dia]["nota"] = nota
                _generar_par_supervisor(wb_maestro, plant_pristina, cal_pristina, persona, dias_info, mes_nombre_excel, anio_num, mes_num, usados)

    wb_maestro.remove(plant_pristina)
    wb_maestro.remove(cal_pristina)
    for nombre in wb_maestro.sheetnames:
        wb_maestro[nombre].sheet_state = "visible"
    wb_maestro.active = 0
    return wb_maestro

