with st.sidebar:
    st.markdown(f"👤 **Analista:** {usuario_sesion}")
    st.markdown(f"💼 **Rol:** {rol_sesion}")
    lista_regiones = ["REGION OZAMA", "REGION VALDESIA", "REGION CIBAO NORTE", "REGION CIBAO SUR", "REGION EL VALLE", "REGION ENRIQUILLO", "REGION ESTE"]
    if "ADMINISTRADOR" in rol_sesion:
        region_actual = st.selectbox("Región de Trabajo (Maestro)", lista_regiones)
    else:
        region_actual = region_sesion
        st.info(f"🌍 **Región Asignada:**\n{region_actual}")
    st.write("---")
    mes_act, anio_act = obtener_periodo_activo(region_actual)
    periodo_act = f"{mes_act} {anio_act}"
    st.header("⚙️ Periodo Operativo")
    st.info(f"**Periodo Activo:**\n{periodo_act}")
    lista_meses = ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"]
    nuevo_mes = st.selectbox("Cambiar Mes", lista_meses, index=lista_meses.index(mes_act) if mes_act in lista_meses else 7)
    nuevo_anio = st.text_input("Cambiar Año", value=anio_act)
    if st.button("Activar Periodo"):
        cambiar_periodo(nuevo_mes, nuevo_anio, region_actual)
        st.success("Periodo actualizado.")
        st.rerun()
    st.write("---")
    st.header("📂 Carga Masiva Regional")
    archivo_migracion = st.file_uploader(f"Subir Excel de {region_actual} (.xlsx)", type=["xlsx"])
    if archivo_migracion is None:
        st.session_state.pop("excel_migracion_hash_procesado", None)
    else:
        try:
            archivo_bytes = archivo_migracion.getvalue()
            archivo_hash = hashlib.sha256(archivo_bytes).hexdigest()

            # El uploader conserva el archivo seleccionado después de un rerun.
            # Sin esta guardia, el mismo Excel se importaba infinitamente.
            if st.session_state.get("excel_migracion_hash_procesado") != archivo_hash:
                df_raw = pd.read_excel(io.BytesIO(archivo_bytes), header=None)
                if df_raw.empty:
                    raise ValueError("El Excel está vacío.")

                start_row = None
                for idx, row in df_raw.iterrows():
                    row_str = {
                        str(cell).strip().upper()
                        for cell in row.values
                        if not pd.isna(cell)
                    }
                    if (
                        any("CEDULA" in celda or "CÉDULA" in celda for celda in row_str)
                        or any("NOMBRE" in celda for celda in row_str)
                    ):
                        start_row = idx
                        break

                if start_row is None:
                    raise ValueError(
                        "No se encontró una fila de encabezados con NOMBRE o CÉDULA."
                    )

                df_clean = df_raw.iloc[start_row:].copy()
                encabezados = []
                encabezados_usados = {}
                for posicion, valor in enumerate(df_clean.iloc[0]):
                    if pd.isna(valor) or not str(valor).strip():
                        encabezado = f"COLUMNA_{posicion + 1}"
                    else:
                        encabezado = " ".join(
                            str(valor).strip().upper().replace(".", "").split()
                        )
                    repeticion = encabezados_usados.get(encabezado, 0)
                    encabezados_usados[encabezado] = repeticion + 1
                    if repeticion:
                        encabezado = f"{encabezado}_{repeticion + 1}"
                    encabezados.append(encabezado)

                df_clean.columns = encabezados
                df_clean = df_clean.iloc[1:].reset_index(drop=True)
                col_cedula = next(
                    (
                        c for c in df_clean.columns
                        if "CEDULA" in str(c) or "CÉDULA" in str(c)
                    ),
                    None,
                )
                col_nombre = next(
                    (c for c in df_clean.columns if "NOMBRE" in str(c)),
                    None,
                )
                col_apellido = next(
                    (c for c in df_clean.columns if "APELLIDO" in str(c)),
                    None,
                )

                if not col_cedula or not col_nombre:
                    raise ValueError(
                        "El Excel debe incluir columnas identificables de NOMBRE y CÉDULA."
                    )

                def valor_excel(fila, nombres, predeterminado=""):
                    for nombre in nombres:
                        if nombre in fila.index:
                            valor = fila[nombre]
                            if not pd.isna(valor):
                                return valor
                    return predeterminado

                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    conteo_altas, conteo_updates = 0, 0
                    for _, row in df_clean.iterrows():
                        cedula_valor = row[col_cedula]
                        nombre_valor = row[col_nombre]
                        if (
                            pd.isna(cedula_valor)
                            or pd.isna(nombre_valor)
                            or "TOTAL" in str(nombre_valor).upper()
                        ):
                            continue

                        ced_clean = str(cedula_valor).strip().replace("-", "")
                        nom_clean = str(nombre_valor).strip().upper()
                        ape_valor = row[col_apellido] if col_apellido else ""
                        ape_clean = (
                            str(ape_valor).strip().upper()
                            if not pd.isna(ape_valor)
                            else ""
                        )
                        if (
                            len(ced_clean) < 5
                            or not nom_clean
                            or "ELABORADO" in nom_clean
                            or "DRA" in nom_clean
                        ):
                            continue

                        cargo_clean = str(
                            valor_excel(
                                row,
                                ("CARGO", "DEF_CARGO"),
                                "PROMOTOR DE SALUD",
                            )
                        ).strip().upper()
                        cta_clean = str(
                            valor_excel(
                                row,
                                ("CTA BANCARIA", "NO DE CUENTA", "CUENTA"),
                            )
                        ).strip()
                        lugar_clean = str(
                            valor_excel(
                                row,
                                ("LUGAR DESIGNADO NOMINA",),
                                "SECCION DE TB- SRS METROPOLITANO",
                            )
                        ).strip().upper()
                        centro_str = str(
                            valor_excel(
                                row,
                                ("LUGAR VISITADO",),
                                "CPN GENERAL",
                            )
                        ).strip().upper()
                        cursor.execute(
                            "INSERT OR IGNORE INTO centros (nombre, region) VALUES (?, ?)",
                            (centro_str, region_actual),
                        )
                        cursor.execute(
                            "SELECT id FROM centros WHERE nombre=? AND region=?",
                            (centro_str, region_actual),
                        )
                        res_c = cursor.fetchone()
                        c_id = res_c[0] if res_c else None
                        cursor.execute(
                            "SELECT id FROM promotores WHERE cedula=?",
                            (ced_clean,),
                        )
                        existe = cursor.fetchone()
                        if existe:
                            cursor.execute(
                                """
                                UPDATE promotores
                                SET nombre=?, apellidos=?, cuenta=?, cargo=?,
                                    lugar_nomina=?, centro_id=?, region=?, activo=1
                                WHERE cedula=?
                                """,
                                (
                                    nom_clean,
                                    ape_clean,
                                    cta_clean,
                                    cargo_clean,
                                    lugar_clean,
                                    c_id,
                                    region_actual,
                                    ced_clean,
                                ),
                            )
                            conteo_updates += 1
                        else:
                            cursor.execute(
                                """
                                INSERT INTO promotores
                                (nombre, apellidos, cedula, cuenta, cargo,
                                 lugar_nomina, centro_id, region, activo)
                                VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)
                                """,
                                (
                                    nom_clean,
                                    ape_clean,
                                    ced_clean,
                                    cta_clean,
                                    cargo_clean,
                                    lugar_clean,
                                    c_id,
                                    region_actual,
                                ),
                            )
                            conteo_altas += 1
                    conn.commit()

                st.session_state["excel_migracion_hash_procesado"] = archivo_hash
                st.sidebar.success(
                    f"¡Sincronizado! {conteo_altas} altas y {conteo_updates} cambios."
                )
                st.rerun()
            else:
                st.sidebar.caption("Este Excel ya fue procesado.")
        except Exception as e:
            st.sidebar.error(f"Error: {e}")
    if st.button("🚪 Cerrar Sesión"):
        st.session_state.autenticado = False
        st.rerun()

opciones_tabs = [
    "📅 Transcribir Evidencias",
    "👥 Maestro de Personal",
    "📊 Reportes e Impresión",
    "🧾 Generar Expedientes (Viáticos)",
]
if "ADMINISTRADOR" in rol_sesion:
    opciones_tabs.append("🔐 Creación de Usuarios")

pestanas = st.tabs(opciones_tabs)

# ------------------------------------------------------------------
# PESTAÑA 1: TRANSCRIBIR EVIDENCIAS
# ------------------------------------------------------------------
with pestanas[0]:
    st.header(f"📅 Transcripción de Evidencias — {periodo_act}")

    with sqlite3.connect(DB_NAME) as conn:
        df_prom = pd.read_sql_query("""
            SELECT p.id, p.nombre, p.apellidos, p.cedula, p.cargo, p.tipo, p.sueldo,
                   p.asignacion_diaria,
                   c.nombre AS centro_asignado
            FROM promotores p LEFT JOIN centros c ON p.centro_id = c.id
            WHERE p.region=? AND p.activo=1
            ORDER BY UPPER(p.nombre), UPPER(p.apellidos)
        """, conn, params=(region_actual,))

    if df_prom.empty:
        st.warning("No hay personal activo registrado para esta región. Cargue el Excel de personal en la barra lateral o agréguelo en Maestro de Personal.")
    else:
        df_prom["etiqueta"] = df_prom["nombre"] + " " + df_prom["apellidos"] + " (C.I. " + df_prom["cedula"] + ")"
        promotor_sel = st.selectbox("Seleccione Personal", df_prom["etiqueta"])
        fila_prom_sel = df_prom.loc[df_prom["etiqueta"] == promotor_sel].iloc[0]
        promotor_id = int(fila_prom_sel["id"])
        tipo_persona_sel = fila_prom_sel["tipo"] or "PROMOTOR"
        cargo_persona_sel = fila_prom_sel["cargo"] or ""
        centro_asignado_sel = fila_prom_sel["centro_asignado"] or ""
        tarifa_persona_sel = asignacion_diaria_persona(
            cargo_persona_sel,
            fila_prom_sel["asignacion_diaria"],
        )
        es_promotor = es_cargo_promotor(cargo_persona_sel)
        clave_editor = f"editor_visitas_{promotor_id}_{periodo_act}"

        st.caption(
            f"Tarifa estándar de transporte para **{cargo_persona_sel or 'este cargo'}**: "
            f"**RD$ {tarifa_persona_sel:,.2f} por día**. El monto se calcula automáticamente al marcar '¿Visitó?' "
            "para mitigar errores de digitación."
        )

        if es_promotor:
            if centro_asignado_sel:
                st.caption(
                    f"🏥 Centro asignado: **{centro_asignado_sel}**. Se precarga en todos los días del mes; "
                    "edítelo solo en los días puntuales en que la persona fue movida a otro centro. "
                    "Para cambiar el centro asignado de forma permanente, hágalo en Maestro de Personal."
                )
            else:
                st.caption("⚠️ Este promotor no tiene un centro asignado en Maestro de Personal. Escriba el centro manualmente por día, o asígneselo uno en Maestro de Personal para que se precargue solo.")
        else:
            st.caption("ℹ️ Este personal no tiene un centro fijo asignado (visita distintos centros durante el mes); escriba el centro correspondiente en cada día.")

        # ------------------------------------------------------------
        # SUELDO MENSUAL — editable y reutilizable por persona
        # ------------------------------------------------------------
        st.write("---")
        st.subheader("💵 Sueldo Mensual")

        sueldo_guardado_raw = fila_prom_sel["sueldo"]
        try:
            sueldo_guardado = float(sueldo_guardado_raw) if sueldo_guardado_raw not in (None, "") else 0.0
        except (TypeError, ValueError):
            sueldo_guardado = 0.0
        sueldo_sugerido = sueldo_estandar(cargo_persona_sel)
        sueldo_valor_inicial = sueldo_guardado if sueldo_guardado > 0 else sueldo_sugerido

        col_sueldo_1, col_sueldo_2 = st.columns([2, 1])
        with col_sueldo_1:
            nuevo_sueldo = st.number_input(
                f"Sueldo mensual de {promotor_sel.split(' (C.I.')[0]} (RD$)",
                min_value=0.0,
                value=float(sueldo_valor_inicial),
                step=100.0,
                format="%.2f",
                key=f"sueldo_input_{promotor_id}",
                help=(
                    f"Sueldo estándar sugerido según el cargo ({cargo_persona_sel or 'sin cargo'}): "
                    f"RD$ {sueldo_sugerido:,.2f}. Puede modificarlo libremente; el valor que guarde aquí "
                    "quedará asociado a esta persona y se reutilizará automáticamente en los próximos meses."
                ),
            )
        with col_sueldo_2:
            st.write("")
            st.write("")
            if st.button("💾 Guardar Sueldo", key=f"btn_guardar_sueldo_{promotor_id}"):
                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    cursor.execute("UPDATE promotores SET sueldo=? WHERE id=?", (nuevo_sueldo, promotor_id))
                    conn.commit()
                st.success("Sueldo actualizado y guardado para este personal.")
                st.rerun()

        if sueldo_guardado <= 0:
            st.caption("ℹ️ Esta persona aún no tiene un sueldo guardado; se está mostrando el valor estándar sugerido según su cargo. Guárdelo para fijarlo definitivamente.")

        st.write("---")

        if es_promotor:
            col_reset, _ = st.columns([1, 3])
            with col_reset:
                if st.button("🧹 Restablecer Centro Asignado", key=f"btn_reset_centro_{promotor_id}"):
                    if clave_editor in st.session_state:
                        del st.session_state[clave_editor]
                    st.session_state[f"forzar_reset_{clave_editor}"] = True
                    st.rerun()

        forzar_reset = st.session_state.pop(f"forzar_reset_{clave_editor}", False)

        mes_num_activo = MESES_NUM.get(mes_act.strip().upper(), datetime.date.today().month)
        try:
            anio_num_activo = int(anio_act)
        except (TypeError, ValueError):
            anio_num_activo = datetime.date.today().year
        dias_no_laborables = obtener_dias_no_laborables(anio_num_activo, mes_num_activo)

        if dias_no_laborables:
            resumen_no_laborables = ", ".join(f"{d} ({m})" for d, m in sorted(dias_no_laborables.items()))
            st.caption(f"🚫 Días no laborables en {periodo_act} (no se pueden marcar como visitados): {resumen_no_laborables}.")

        with sqlite3.connect(DB_NAME) as conn:
            df_vis = pd.read_sql_query(
                "SELECT dia, visito, centro_visitado FROM visitas WHERE promotor_id=? AND periodo=? AND region=?",
                conn, params=(promotor_id, periodo_act, region_actual)
            )

        base = pd.DataFrame({"dia": list(range(1, 32))})
        df_editor = base.merge(df_vis, on="dia", how="left")
        df_editor["visito"] = df_editor["visito"].fillna(0).astype(int).astype(bool)
        df_editor["centro_visitado"] = df_editor["centro_visitado"].fillna("")

        if es_promotor and forzar_reset:
            df_editor["centro_visitado"] = df_editor["visito"].apply(lambda v: centro_asignado_sel if v else "")

        df_editor["monto (RD$ automático)"] = df_editor["visito"].apply(lambda v: tarifa_persona_sel if v else 0.0)

        if es_promotor:
            st.caption("Marque los días visitados. Al guardar, el centro asignado se completa automáticamente en esos días (puede editarlo si ese día fue a otro centro); el monto se calcula solo con la tarifa del cargo.")
        else:
            st.caption("Marque los días visitados e indique el centro correspondiente — es obligatorio para poder guardar. El monto se calcula solo con la tarifa del cargo.")

        df_resultado = st.data_editor(
            df_editor,
            column_config={
                "dia": st.column_config.NumberColumn("Día", disabled=True),
                "visito": st.column_config.CheckboxColumn("¿Visitó?"),
                "centro_visitado": st.column_config.TextColumn("Centro Visitado"),
                "monto (RD$ automático)": st.column_config.NumberColumn("Monto (RD$)", disabled=True, format="%.2f"),
            },
            hide_index=True,
            use_container_width=True,
            key=clave_editor
        )

        if st.button("💾 Guardar Evidencias del Mes"):
            errores = []
            for idx in df_resultado.index:
                visito_bool = bool(df_resultado.loc[idx, "visito"])
                centro_txt = str(df_resultado.loc[idx, "centro_visitado"]).strip()
                # Autocompletar el centro asignado para promotores en el momento
                # de guardar, si el día fue marcado y no se escribió un centro.
                if visito_bool and es_promotor and not centro_txt:
                    centro_txt = centro_asignado_sel
                    df_resultado.loc[idx, "centro_visitado"] = centro_txt

                dia_num = int(df_resultado.loc[idx, "dia"])
                if visito_bool and dia_num in dias_no_laborables:
                    errores.append(f"Día {dia_num} ({dias_no_laborables[dia_num]}): es un día no laborable y no puede marcarse como visitado.")
                elif visito_bool and not es_promotor and not centro_txt:
                    errores.append(f"Día {dia_num}: falta indicar el centro visitado antes de guardar.")

            if errores:
                st.error("No se pudo guardar. Corrija lo siguiente:\n\n" + "\n".join(f"- {e}" for e in errores))
            else:
                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    for _, fila in df_resultado.iterrows():
                        visito_bool = bool(fila["visito"])
                        monto_final = tarifa_persona_sel if visito_bool else 0.0
                        cursor.execute(
                            "INSERT OR REPLACE INTO visitas (promotor_id, periodo, dia, visito, centro_visitado, monto, region) VALUES (?, ?, ?, ?, ?, ?, ?)",
                            (promotor_id, periodo_act, int(fila["dia"]), int(visito_bool), str(fila["centro_visitado"]).strip().upper(), monto_final, region_actual)
                        )
                    conn.commit()
                st.success("Evidencias guardadas correctamente (montos y centro aplicados automáticamente según corresponda).")
                st.rerun()

# ------------------------------------------------------------------
# PESTAÑA 2: MAESTRO DE PERSONAL
# ------------------------------------------------------------------
with pestanas[1]:
    st.header(f"👥 Maestro de Personal — {region_actual}")

    with sqlite3.connect(DB_NAME) as conn:
        df_centros = pd.read_sql_query("SELECT id, nombre FROM centros WHERE region=? ORDER BY nombre", conn, params=(region_actual,))
        df_personal = pd.read_sql_query("""
            SELECT p.id, p.nombre, p.apellidos, p.cedula, p.cuenta, p.cargo, p.tipo,
                   p.sueldo, p.asignacion_diaria, p.lugar_nomina,
                   c.nombre AS centro, p.activo
            FROM promotores p LEFT JOIN centros c ON p.centro_id = c.id
            WHERE p.region=? ORDER BY UPPER(p.nombre), UPPER(p.apellidos)
        """, conn, params=(region_actual,))

    if not df_personal.empty:
        df_personal["asignacion_diaria_rd$"] = df_personal.apply(
            lambda fila: asignacion_diaria_persona(
                fila["cargo"],
                fila["asignacion_diaria"],
            ),
            axis=1,
        )

    st.subheader("Personal Registrado")
    st.caption(
        "La asignación diaria se sugiere según el cargo: Promotor/a RD$ 300, "
        "Psicólogo/a RD$ 700, Supervisor(a) de Promotores RD$ 400 y RD$ 500 "
        "para los demás cargos. Puede modificarla al crear o actualizar el registro."
    )
    # La tabla permite seleccionar una fila y cargarla en el editor inferior.
    # En versiones antiguas de Streamlit se conserva la tabla como fallback.
    filas_seleccionadas = []
    try:
        evento_tabla = st.dataframe(
            df_personal,
            use_container_width=True,
            hide_index=True,
            key="tabla_personal_registrado",
            on_select="rerun",
            selection_mode="single-row",
        )
        if evento_tabla is not None:
            seleccion_tabla = getattr(evento_tabla, "selection", None)
            filas_seleccionadas = list(getattr(seleccion_tabla, "rows", []))
    except TypeError:
        st.dataframe(df_personal, use_container_width=True, hide_index=True)
        st.warning("Actualice Streamlit para seleccionar filas directamente en la tabla.")

    FORM_KEYS_PERSONAL = (
        "personal_form_nombre",
        "personal_form_apellidos",
        "personal_form_cedula",
        "personal_form_cuenta",
        "personal_form_cargo_opcion",
        "personal_form_cargo_custom",
        "personal_form_sueldo",
        "personal_form_asignacion",
        "personal_form_cargo_anterior",
        "personal_form_centro",
        "personal_form_centro_nuevo",
        "personal_form_lugar_nomina",
    )

    def texto_celda(valor):
        return "" if valor is None or pd.isna(valor) else str(valor)

    def limpiar_formulario_personal():
        st.session_state.pop("personal_edicion_id", None)
        for clave in FORM_KEYS_PERSONAL:
            st.session_state.pop(clave, None)

    # Cuando el botón se pulsa, los widgets ya fueron creados en este rerun y
    # Streamlit no permite borrar sus claves inmediatamente. Se programa el
    # borrado para el siguiente rerun, antes de volver a dibujar los widgets.
    if st.session_state.pop("personal_reset_requested", False):
        limpiar_formulario_personal()
        st.session_state["personal_skip_selection_once"] = True

    omitir_seleccion_guardada = st.session_state.pop("personal_skip_selection_once", False)

    # Cargar la fila seleccionada una sola vez. Si no se compara el id, cada
    # rerun provocado por un campo de texto sobrescribe lo que se está editando.
    if not omitir_seleccion_guardada and filas_seleccionadas and not df_personal.empty:
        indice_seleccionado = int(filas_seleccionadas[0])
        if 0 <= indice_seleccionado < len(df_personal):
            fila_cargada = df_personal.iloc[indice_seleccionado]
            id_cargado = int(fila_cargada["id"])
            if st.session_state.get("personal_edicion_id") != id_cargado:
                cargo_cargado = "" if pd.isna(fila_cargada["cargo"]) else str(fila_cargada["cargo"]).strip()
                centro_cargado = "" if pd.isna(fila_cargada["centro"]) else str(fila_cargada["centro"]).strip()
                opcion_cargo = (
                    cargo_cargado
                    if cargo_cargado in CARGOS_SUGERIDOS
                    else "OTRO (escribir cargo)"
                )
                sueldo_cargado = fila_cargada["sueldo"]
                try:
                    sueldo_cargado = float(sueldo_cargado) if not pd.isna(sueldo_cargado) else 0.0
                except (TypeError, ValueError):
                    sueldo_cargado = 0.0
                asignacion_cargada = fila_cargada["asignacion_diaria"]
                asignacion_cargada = asignacion_diaria_persona(
                    cargo_cargado,
                    asignacion_cargada,
                )

                st.session_state["personal_edicion_id"] = id_cargado
                st.session_state["personal_form_nombre"] = texto_celda(fila_cargada["nombre"])
                st.session_state["personal_form_apellidos"] = texto_celda(fila_cargada["apellidos"])
                st.session_state["personal_form_cedula"] = texto_celda(fila_cargada["cedula"])
                st.session_state["personal_form_cuenta"] = texto_celda(fila_cargada["cuenta"])
                st.session_state["personal_form_cargo_opcion"] = opcion_cargo
                st.session_state["personal_form_cargo_custom"] = (
                    cargo_cargado if opcion_cargo == "OTRO (escribir cargo)" else ""
                )
                st.session_state["personal_form_sueldo"] = sueldo_cargado
                st.session_state["personal_form_asignacion"] = float(asignacion_cargada)
                st.session_state["personal_form_cargo_anterior"] = cargo_cargado
                st.session_state["personal_form_centro"] = centro_cargado or "-- Sin Centro --"
                st.session_state["personal_form_centro_nuevo"] = ""
                st.session_state["personal_form_lugar_nomina"] = texto_celda(fila_cargada["lugar_nomina"])

    id_edicion = st.session_state.get("personal_edicion_id")
    if id_edicion is not None and (
        df_personal.empty
        or int(id_edicion) not in set(df_personal["id"].astype(int).tolist())
    ):
        limpiar_formulario_personal()
        id_edicion = None

    st.write("---")
    col_a, col_b = st.columns(2)

    with col_a:
        st.subheader("✏️ Editar / ➕ Agregar Personal")
        if id_edicion is not None:
            st.info("Editando el registro seleccionado. Cambie los datos y presione **Actualizar Personal**.")
            if st.button("Limpiar selección / Nuevo registro", key="btn_nuevo_personal"):
                st.session_state["personal_reset_requested"] = True
                st.rerun()
        else:
            st.caption("Seleccione una fila de la tabla para actualizarla o complete estos campos para agregar personal nuevo.")

        # Se evita st.form porque sus widgets no ejecutan un rerun al cambiar
        # Cargo/Centro; por eso los campos condicionales no se habilitaban.
        f_nombre = st.text_input("Nombre", key="personal_form_nombre")
        f_apellidos = st.text_input("Apellidos", key="personal_form_apellidos")
        f_cedula = st.text_input("Cédula (sin guiones)", key="personal_form_cedula")
        f_cuenta = st.text_input("Cuenta Bancaria", key="personal_form_cuenta")

        opciones_cargo = list(CARGOS_SUGERIDOS)
        if st.session_state.get("personal_form_cargo_opcion") not in opciones_cargo:
            st.session_state["personal_form_cargo_opcion"] = opciones_cargo[0]
        f_cargo_sel = st.selectbox("Cargo", opciones_cargo, key="personal_form_cargo_opcion")
        if f_cargo_sel == "OTRO (escribir cargo)":
            f_cargo_custom = st.text_input("Escriba el Cargo", key="personal_form_cargo_custom")
        else:
            f_cargo_custom = ""
            st.session_state["personal_form_cargo_custom"] = ""
        cargo_previsto = (
            f_cargo_custom.strip().upper()
            if f_cargo_sel == "OTRO (escribir cargo)"
            else f_cargo_sel.strip().upper()
        )

        tarifa_sugerida = tarifa_estandar(cargo_previsto)
        cargo_anterior = st.session_state.get("personal_form_cargo_anterior")
        if cargo_anterior is None:
            st.session_state["personal_form_cargo_anterior"] = cargo_previsto
        elif cargo_anterior != cargo_previsto:
            # Si el usuario no había personalizado el monto, actualizar el
            # cargo también actualiza su sugerencia. Si ya lo cambió a mano,
            # se conserva ese valor personalizado.
            try:
                asignacion_actual = float(
                    st.session_state.get("personal_form_asignacion", 0)
                )
            except (TypeError, ValueError):
                asignacion_actual = 0.0
            tarifa_anterior = tarifa_estandar(cargo_anterior)
            if abs(asignacion_actual - tarifa_anterior) < 0.01:
                st.session_state["personal_form_asignacion"] = float(tarifa_sugerida)
            st.session_state["personal_form_cargo_anterior"] = cargo_previsto

        f_tipo = "PROMOTOR" if es_cargo_promotor(cargo_previsto) else "SUPERVISOR"
        if f_tipo == "PROMOTOR":
            st.caption("✅ Clasificado automáticamente como **Promotor** según el cargo. Puede asignarle un centro fijo.")
        else:
            st.caption("✅ Clasificado automáticamente como **personal no-promotor** según el cargo. Recibirá Plantilla + Calendario y no tendrá centro fijo.")
        st.caption(
            f"Asignación diaria sugerida para este cargo: **RD$ {tarifa_sugerida:,.2f}**. "
            "Puede modificarla si este personal tiene un monto diferente."
        )

        if "personal_form_sueldo" not in st.session_state:
            st.session_state["personal_form_sueldo"] = float(sueldo_estandar(cargo_previsto))
        f_sueldo = st.number_input(
            "Sueldo Mensual RD$",
            min_value=0.0,
            step=500.0,
            format="%.2f",
            key="personal_form_sueldo",
            help="El sueldo se guarda para esta persona y se utilizará al generar los expedientes.",
        )
        if "personal_form_asignacion" not in st.session_state:
            st.session_state["personal_form_asignacion"] = float(tarifa_sugerida)
        f_asignacion = st.number_input(
            "Asignación Diaria RD$",
            min_value=0.0,
            step=50.0,
            format="%.2f",
            key="personal_form_asignacion",
            help=(
                "Monto diario usado al marcar una visita y al generar los expedientes. "
                "El valor sugerido depende del cargo, pero puede personalizarlo."
            ),
        )

        f_centro = "-- Sin Centro --"
        f_centro_nuevo = ""
        if f_tipo == "PROMOTOR":
            lista_centros = df_centros["nombre"].dropna().astype(str).tolist() if not df_centros.empty else []
            centro_actual_form = st.session_state.get("personal_form_centro", "-- Sin Centro --")
            if centro_actual_form not in lista_centros and centro_actual_form not in ("-- Sin Centro --", "-- Nuevo Centro --"):
                lista_centros.append(centro_actual_form)
            opciones_centro = ["-- Sin Centro --"] + sorted(set(lista_centros)) + ["-- Nuevo Centro --"]
            if centro_actual_form not in opciones_centro:
                st.session_state["personal_form_centro"] = "-- Sin Centro --"
            f_centro = st.selectbox(
                "Centro Asignado",
                opciones_centro,
                key="personal_form_centro",
                help="El centro se precargará automáticamente al registrar evidencias.",
            )
            if f_centro == "-- Nuevo Centro --":
                f_centro_nuevo = st.text_input("Nombre del Nuevo Centro", key="personal_form_centro_nuevo")
                st.caption("El nuevo centro se creará automáticamente al guardar.")
        else:
            st.caption("Este personal visita distintos centros durante el mes y no se le asigna un centro fijo.")
            st.session_state["personal_form_centro"] = "-- Sin Centro --"

        f_lugar_nomina = st.text_input("Lugar Designado Nómina", key="personal_form_lugar_nomina")
        if not f_lugar_nomina:
            f_lugar_nomina = "SECCION DE TB- SRS METROPOLITANO"

        col_guardar, col_cancelar = st.columns(2)
        with col_guardar:
            texto_guardar = "Actualizar Personal" if id_edicion is not None else "Guardar Personal"
            guardar_personal = st.button(texto_guardar, type="primary", key="btn_guardar_personal")
        with col_cancelar:
            cancelar_personal = st.button("Cancelar / Limpiar", key="btn_cancelar_personal")

        if cancelar_personal:
            st.session_state["personal_reset_requested"] = True
            st.rerun()

        if guardar_personal:
            errores_form = []
            if not f_cedula.strip() or not f_nombre.strip():
                errores_form.append("Cédula y Nombre son obligatorios.")
            if f_cargo_sel == "OTRO (escribir cargo)" and not f_cargo_custom.strip():
                errores_form.append("Escriba el cargo.")

            centro_final = ""
            if f_tipo == "PROMOTOR":
                if f_centro == "-- Nuevo Centro --":
                    centro_final = f_centro_nuevo.strip().upper()
                    if not centro_final:
                        errores_form.append("Escriba el nombre del nuevo centro o seleccione un centro existente.")
                elif f_centro != "-- Sin Centro --":
                    centro_final = f_centro.strip().upper()

            if errores_form:
                st.error("\n".join(f"- {error}" for error in errores_form))
            else:
                ced_clean = f_cedula.strip().replace("-", "").replace(" ", "")
                nombre_final = f_nombre.strip().upper()
                apellidos_final = f_apellidos.strip().upper()
                cuenta_final = f_cuenta.strip()
                nomina_final = f_lugar_nomina.strip().upper()

                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    c_id = None
                    if centro_final:
                        cursor.execute(
                            "INSERT OR IGNORE INTO centros (nombre, region) VALUES (?, ?)",
                            (centro_final, region_actual),
                        )
                        cursor.execute(
                            "SELECT id FROM centros WHERE nombre=? AND region=?",
                            (centro_final, region_actual),
                        )
                        resultado_centro = cursor.fetchone()
                        c_id = resultado_centro[0] if resultado_centro else None

                    # Al editar se actualiza por id, incluso si se corrige la
                    # cédula. Nunca se modifica accidentalmente otra persona.
                    if id_edicion is not None:
                        cursor.execute(
                            "SELECT id FROM promotores WHERE cedula=? AND id<>?",
                            (ced_clean, int(id_edicion)),
                        )
                        duplicado = cursor.fetchone()
                        if duplicado:
                            st.error("La cédula indicada ya pertenece a otro registro.")
                            conn.rollback()
                        else:
                            cursor.execute(
                                """UPDATE promotores
                                   SET nombre=?, apellidos=?, cedula=?, cuenta=?, cargo=?,
                                       tipo=?, sueldo=?, asignacion_diaria=?, lugar_nomina=?, centro_id=?,
                                       region=?, activo=1
                                   WHERE id=?""",
                                (
                                    nombre_final, apellidos_final, ced_clean, cuenta_final,
                                    cargo_previsto, f_tipo, f_sueldo, f_asignacion, nomina_final, c_id,
                                    region_actual, int(id_edicion),
                                ),
                            )
                            conn.commit()
                            st.session_state["personal_flash"] = "Personal actualizado correctamente."
                            st.session_state["personal_reset_requested"] = True
                            st.rerun()
                    else:
                        cursor.execute("SELECT id FROM promotores WHERE cedula=?", (ced_clean,))
                        existente = cursor.fetchone()
                        if existente:
                            st.error("Ya existe un registro con esa cédula. Seleccione la fila correspondiente para actualizarlo.")
                            conn.rollback()
                        else:
                            cursor.execute(
                                """INSERT INTO promotores
                                   (nombre, apellidos, cedula, cuenta, cargo, tipo, sueldo, asignacion_diaria,
                                    lugar_nomina, centro_id, region, activo)
                                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)""",
                                (
                                    nombre_final, apellidos_final, ced_clean, cuenta_final,
                                    cargo_previsto, f_tipo, f_sueldo, f_asignacion, nomina_final, c_id,
                                    region_actual,
                                ),
                            )
                            conn.commit()
                            st.session_state["personal_flash"] = "Personal guardado correctamente."
                            st.session_state["personal_reset_requested"] = True
                            st.rerun()

        if st.session_state.get("personal_flash"):
            st.success(st.session_state.pop("personal_flash"))

    with col_b:
        st.subheader("🚫 Desactivar / Reactivar Promotor")
        if not df_personal.empty:
            df_personal["etiqueta"] = df_personal["nombre"] + " " + df_personal["apellidos"] + " (C.I. " + df_personal["cedula"] + ")"
            sel_desactivar = st.selectbox("Seleccione Promotor", df_personal["etiqueta"], key="sel_desact")
            fila_sel = df_personal.loc[df_personal["etiqueta"] == sel_desactivar].iloc[0]
            estado_actual = "Activo" if fila_sel["activo"] == 1 else "Inactivo"
            st.info(f"Estado actual: **{estado_actual}**")
            nuevo_estado = 0 if fila_sel["activo"] == 1 else 1
            etiqueta_boton = "Desactivar" if fila_sel["activo"] == 1 else "Reactivar"
            if st.button(f"{etiqueta_boton} Promotor"):
                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    cursor.execute("UPDATE promotores SET activo=? WHERE id=?", (nuevo_estado, int(fila_sel["id"])))
                    conn.commit()
                st.success(f"Promotor {etiqueta_boton.lower()}do correctamente.")
                st.rerun()

            st.write("---")
            st.subheader("🗑️ Eliminar Registro Permanentemente")
            st.caption("Esto borra a la persona y TODO su historial de evidencias registradas. No se puede deshacer — use 'Desactivar' arriba si solo quiere ocultarlo sin perder el historial.")
            sel_eliminar = st.selectbox("Seleccione Registro a Eliminar", df_personal["etiqueta"], key="sel_elim")
            fila_elim = df_personal.loc[df_personal["etiqueta"] == sel_eliminar].iloc[0]
            confirmar_borrado = st.checkbox(f"Sí, entiendo que se borrará permanentemente a {sel_eliminar} y su historial.", key="chk_confirmar_elim")
            if st.button("🗑️ Eliminar Definitivamente", disabled=not confirmar_borrado):
                with sqlite3.connect(DB_NAME) as conn:
                    cursor = conn.cursor()
                    id_elim = int(fila_elim["id"])
                    cursor.execute("DELETE FROM visitas WHERE promotor_id=?", (id_elim,))
                    cursor.execute("DELETE FROM notas_cronograma WHERE promotor_id=?", (id_elim,))
                    cursor.execute("DELETE FROM promotores WHERE id=?", (id_elim,))
                    conn.commit()
                st.success("Registro eliminado permanentemente.")
                st.rerun()
        else:
            st.info("No hay promotores registrados aún.")

# ------------------------------------------------------------------
# PESTAÑA 3: REPORTES E IMPRESIÓN
# ------------------------------------------------------------------
with pestanas[2]:
    st.header(f"📊 Reportes e Impresión — {region_actual}")

    with sqlite3.connect(DB_NAME) as conn:
        df_reporte = pd.read_sql_query("""
            SELECT p.nombre, p.apellidos, p.cedula, p.cargo, p.tipo,
                   COALESCE(SUM(v.visito), 0) AS dias_visitados,
                   COALESCE(SUM(v.monto), 0) AS monto_total
            FROM promotores p
            LEFT JOIN visitas v ON p.id = v.promotor_id AND v.periodo = ? AND v.region = ?
            WHERE p.region = ? AND p.activo = 1
            GROUP BY p.id
            ORDER BY UPPER(p.nombre), UPPER(p.apellidos)
        """, conn, params=(periodo_act, region_actual, region_actual))

    st.subheader(f"Consolidado del Periodo: {periodo_act}")
    if df_reporte.empty:
        st.info("No hay datos de promotores para esta región y periodo.")
    else:
        st.dataframe(df_reporte, use_container_width=True, hide_index=True)
        total_general = df_reporte["monto_total"].sum()
        st.metric("💰 Monto Total a Pagar", f"RD$ {total_general:,.2f}")

        buffer_excel = io.BytesIO()
        with pd.ExcelWriter(buffer_excel, engine="openpyxl") as writer:
            df_reporte.to_excel(writer, index=False, sheet_name="Reporte")
        buffer_excel.seek(0)

        st.download_button(
            label="⬇️ Descargar Reporte en Excel",
            data=buffer_excel,
            file_name=f"reporte_{region_actual.replace(' ', '_')}_{periodo_act.replace(' ', '_')}.xlsx",
            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
        )

# ------------------------------------------------------------------
# PESTAÑA 4: GENERAR EXPEDIENTES DE VIÁTICOS (plantilla oficial clonada)
# ------------------------------------------------------------------
with pestanas[3]:
    st.header(f"🧾 Generar Expedientes de Viáticos — {periodo_act}")
    st.caption(
        "Se clona la plantilla oficial real (con sus fórmulas, estilos e imágenes originales). "
        "Los promotores reciben solo la Plantilla; el resto del personal (supervisores, enfermeras, "
        "analistas, psicólogos, etc.) recibe Plantilla + Calendario, igual que en los archivos originales. "
        "El Consolidado Completo del mes se incluye siempre, con todo el personal que trabajó ese periodo. "
        "El rótulo de cargo y el sueldo mensual de cada persona se imprimen automáticamente según lo cargado "
        "en el sistema."
    )

    with sqlite3.connect(DB_NAME) as conn:
        df_todos = pd.read_sql_query("""
            SELECT p.id, p.nombre, p.apellidos, p.cedula, p.cuenta, p.cargo,
                   p.tipo, p.sueldo, p.asignacion_diaria, p.lugar_nomina
            FROM promotores p
            WHERE p.region=? AND p.activo=1
            ORDER BY UPPER(p.nombre), UPPER(p.apellidos)
        """, conn, params=(region_actual,))
        df_trabajaron = pd.read_sql_query("""
            SELECT DISTINCT promotor_id FROM visitas
            WHERE region=? AND periodo=? AND visito=1
        """, conn, params=(region_actual, periodo_act))

    # El cargo es la fuente de verdad. Recalcular el tipo aquí evita que un
    # registro antiguo, importado con el valor por defecto PROMOTOR, termine
    # generando el expediente equivocado.
    if not df_todos.empty:
        df_todos["tipo"] = df_todos["cargo"].fillna("").apply(
            lambda cargo: "PROMOTOR" if es_cargo_promotor(cargo) else "SUPERVISOR"
        )
        for columna in ("nombre", "apellidos", "cedula", "cuenta", "cargo", "lugar_nomina"):
            df_todos[columna] = df_todos[columna].fillna("").astype(str)

    ids_trabajaron = set(df_trabajaron["promotor_id"].tolist())
    df_activos_periodo = df_todos[df_todos["id"].isin(ids_trabajaron)].copy()

    if df_activos_periodo.empty:
        st.info("Nadie tiene evidencias registradas (¿Visitó? marcado) en el periodo activo todavía. Registre evidencias en la primera pestaña antes de generar expedientes.")
    else:
        st.success(f"{len(df_activos_periodo)} persona(s) tienen actividad registrada en {periodo_act} y se incluirán en el Consolidado.")

        tipo_filtro = st.radio("Tipo de Personal a imprimir individualmente", ["PROMOTOR", "SUPERVISOR", "Todos"], horizontal=True, key="tipo_filtro_expedientes")
        df_gen = df_activos_periodo if tipo_filtro == "Todos" else df_activos_periodo[df_activos_periodo["tipo"] == tipo_filtro]

        if df_gen.empty:
            st.info("No hay personal con actividad este mes que coincida con el filtro seleccionado.")
        else:
            df_gen = df_gen.copy()
            df_gen["etiqueta"] = df_gen["nombre"] + " " + df_gen["apellidos"] + " (" + df_gen["cargo"].fillna("") + ")"
            modo_sel = st.radio("Selección para expedientes individuales", ["Todos los que trabajaron este mes", "Selección individual"], horizontal=True, key="modo_sel_expedientes")
            if modo_sel == "Todos los que trabajaron este mes":
                seleccionados = df_gen["etiqueta"].tolist()
            else:
                seleccionados = st.multiselect("Seleccione el personal", df_gen["etiqueta"].tolist())

            if st.button("📄 Generar Archivo de Expedientes"):
                if not seleccionados:
                    st.warning("Seleccione al menos una persona para generar los expedientes individuales.")
                else:
                    df_sel = df_gen[df_gen["etiqueta"].isin(seleccionados)]
                    personas_seleccionadas = df_sel.to_dict("records")
                    personas_consolidado = df_activos_periodo.to_dict("records")

                    try:
                        wb_generado = construir_libro_expedientes(
                            personas_seleccionadas, personas_consolidado,
                            region_actual, periodo_act, mes_act, anio_act
                        )
                        buffer_wb = io.BytesIO()
                        wb_generado.save(buffer_wb)
                        buffer_wb.seek(0)
                        st.success(
                            f"Se generó el Consolidado Completo + "
                            f"{len(personas_seleccionadas)} expediente(s) individual(es)."
                        )
                        st.download_button(
                            "⬇️ Descargar Expedientes (Excel)",
                            data=buffer_wb,
                            file_name=f"expedientes_viaticos_{region_actual.replace(' ', '_')}_{periodo_act.replace(' ', '_')}.xlsx",
                            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                        )
                    except Exception as error_expediente:
                        st.error("No se pudo crear el archivo de expedientes. Revise la plantilla oficial o los datos seleccionados.")
                        with st.expander("Ver detalle técnico del error"):
                            st.exception(error_expediente)

# ------------------------------------------------------------------
# PESTAÑA 5: CREACIÓN DE USUARIOS (SOLO ADMINISTRADORES)
# ------------------------------------------------------------------
if "ADMINISTRADOR" in rol_sesion:
    with pestanas[4]:
        st.header("🔐 Creación y Gestión de Usuarios")

        with sqlite3.connect(DB_NAME) as conn:
            df_usuarios = pd.read_sql_query("SELECT usuario, region, rol FROM usuarios ORDER BY usuario", conn)
        st.subheader("Usuarios Registrados")
        st.dataframe(df_usuarios, use_container_width=True, hide_index=True)

        st.write("---")
        st.subheader("➕ Crear Nuevo Usuario")
        with st.form("form_usuario", clear_on_submit=True):
            nu_usuario = st.text_input("Nombre de Usuario")
            nu_password = st.text_input("Contraseña", type="password")
            nu_region = st.selectbox("Región Asignada", lista_regiones + ["TODAS"])
            nu_rol = st.selectbox("Rol", ["ANALISTA REGIONAL", "ADMINISTRADOR", "ADMINISTRADOR NACIONAL"])
            if st.form_submit_button("Crear Usuario"):
                if not nu_usuario.strip() or not nu_password.strip():
                    st.error("Usuario y contraseña son obligatorios.")
                else:
                    hash_pw = hashlib.sha256(nu_password.encode('utf-8')).hexdigest()
                    with sqlite3.connect(DB_NAME) as conn:
                        cursor = conn.cursor()
                        cursor.execute(
                            "INSERT OR REPLACE INTO usuarios VALUES (?, ?, ?, ?)",
                            (nu_usuario.strip().upper(), hash_pw, nu_region, nu_rol)
                        )
                        conn.commit()
                    st.success("Usuario creado/actualizado correctamente.")
                    st.rerun()

        if not df_usuarios.empty:
            st.write("---")
            st.subheader("🗑️ Eliminar Usuario")
            usuarios_disponibles = [u for u in df_usuarios["usuario"].tolist() if u != usuario_sesion]
            if usuarios_disponibles:
                sel_usuario_elim = st.selectbox("Seleccione Usuario a Eliminar", usuarios_disponibles)
                if st.button("🗑️ Eliminar Usuario Definitivamente"):
                    with sqlite3.connect(DB_NAME) as conn:
                        cursor = conn.cursor()
                        cursor.execute("DELETE FROM usuarios WHERE usuario=?", (sel_usuario_elim,))
                        conn.commit()
                    st.success("Usuario eliminado correctamente.")
                    st.rerun()
            else:
                st.caption("No hay otros usuarios para eliminar (no puede eliminar su propia sesión activa).")
